function ws_plugins_performAction($params,$service){
  if(get_pwg_token()!=$params['pwg_token']) return new PwgError(403,'Invalid security token');
  if(!is_webmaster()) return new PwgError(403,l10n('Webmaster status is required.'));
  $plugins=new plugins(); $errors=$plugins->perform_action($params['action'],$params['plugin']);
  if(!empty($errors)) return new PwgError(500,$errors); return true;
}

function ws_plugins_getList($params,$service){
  $plugins=new plugins(); $plugins->sort_fs_plugins('name');
  foreach($plugins->fs_plugins as $plugin_id=>$fs_plugin){
    if(isset($plugins->db_plugins_by_id[$plugin_id])) $state=$plugins->db_plugins_by_id[$plugin_id]['state'];
    else $state='uninstalled';
    $plugin_list[]=array('id'=>$plugin_id,'version'=>$fs_plugin['version'],'state'=>$state);
  }
  return $plugin_list;
}
